insert into public.articles (title, slug, excerpt, body, cover_image_url, category_id, author_id, kind, status, featured, published_at)
values
  ('The Last Video Shop on the Street', 'the-last-video-shop-on-the-street', 'A shop full of tapes nobody rents, run by a man who refuses to close.', '<p>The first time I noticed it, I thought it was a mistake. The second time, I started taking notes. It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly.</p><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday.</p><h2>The people</h2><p>I spoke to a dozen people over three weeks. Each had a different reason for being there, and each, in their own way, had stopped waiting for permission. It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly.</p><blockquote><p>Once you''ve seen it done properly, you can''t go back to doing it badly.</p></blockquote><p>The details matter here: the smell of the place, the sound of footsteps on old floors, the way conversations drift and return. These are the things you can''t plan for and can''t fake.</p><img src="https://picsum.photos/seed/byb-inline-0/1200/700" alt=""><h2>Looking ahead</h2><p>The details matter here: the smell of the place, the sound of footsteps on old floors, the way conversations drift and return. These are the things you can''t plan for and can''t fake. Whether it lasts is almost beside the point. It is here now, and that is enough.</p>', 'https://picsum.photos/seed/byb-the-last-video-shop-on-the-street/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', true, now() - interval '1 days 5 hours'),
  ('Why Everyone Is Learning to Bind Books Again', 'why-everyone-is-learning-to-bind-books-again', 'Glue, thread and a bone folder: the quiet craft winning over a generation of screen-tired hands.', '<p>Nobody tells you that the most interesting things happen just before closing time. I spoke to a dozen people over three weeks. Each had a different reason for being there, and each, in their own way, had stopped waiting for permission.</p><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday.</p><h2>The people</h2><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday. It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly.</p><blockquote><p>Once you''ve seen it done properly, you can''t go back to doing it badly.</p></blockquote><p>It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly.</p><img src="https://picsum.photos/seed/byb-inline-1/1200/700" alt=""><h2>Why it matters</h2><p>It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly. Whether it lasts is almost beside the point. It is here now, and that is enough.</p>', 'https://picsum.photos/seed/byb-why-everyone-is-learning-to-bind-books-again/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, now() - interval '3 days 2 hours'),
  ('A Year of Listening Only to Vinyl', 'a-year-of-listening-only-to-vinyl', 'No playlists, no shuffle, no skipping. What happens when music becomes an appointment.', '<p>It started, as these things often do, with a small decision that turned out not to be small at all. What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday.</p><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday.</p><h2>The people</h2><p>There were setbacks, of course. Plans changed, budgets ran out, the weather refused to cooperate. But every obstacle seemed to sharpen the purpose rather than blunt it. The economics don''t make sense on paper. They rarely do. And yet here it is, thriving in a way that spreadsheets can''t explain.</p><blockquote><p>We''re not trying to be the biggest. We''re trying to still be here in twenty years.</p></blockquote><p>The details matter here: the smell of the place, the sound of footsteps on old floors, the way conversations drift and return. These are the things you can''t plan for and can''t fake.</p><img src="https://picsum.photos/seed/byb-inline-2/1200/700" alt=""><h2>The hard part</h2><p>There were setbacks, of course. Plans changed, budgets ran out, the weather refused to cooperate. But every obstacle seemed to sharpen the purpose rather than blunt it. I left later than I meant to, which is usually the sign of a good day.</p>', 'https://picsum.photos/seed/byb-a-year-of-listening-only-to-vinyl/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, now() - interval '4 days 18 hours'),
  ('The Choir That Sings in Car Parks', 'the-choir-that-sings-in-car-parks', 'Every Thursday at dusk, forty strangers meet on level four.', '<p>Nobody tells you that the most interesting things happen just before closing time. I spoke to a dozen people over three weeks. Each had a different reason for being there, and each, in their own way, had stopped waiting for permission.</p><p>I spoke to a dozen people over three weeks. Each had a different reason for being there, and each, in their own way, had stopped waiting for permission.</p><h2>What it takes</h2><p>The details matter here: the smell of the place, the sound of footsteps on old floors, the way conversations drift and return. These are the things you can''t plan for and can''t fake. I spoke to a dozen people over three weeks. Each had a different reason for being there, and each, in their own way, had stopped waiting for permission.</p><blockquote><p>Once you''ve seen it done properly, you can''t go back to doing it badly.</p></blockquote><p>The economics don''t make sense on paper. They rarely do. And yet here it is, thriving in a way that spreadsheets can''t explain.</p><img src="https://picsum.photos/seed/byb-inline-3/1200/700" alt=""><h2>The hard part</h2><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday. I left later than I meant to, which is usually the sign of a good day.</p>', 'https://picsum.photos/seed/byb-the-choir-that-sings-in-car-parks/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, now() - interval '6 days 12 hours'),
  ('Notes From a Midnight Cinema', 'notes-from-a-midnight-cinema', 'The audience at the 2 a.m. screening is the strangest and kindest you will ever join.', '<p>Nobody tells you that the most interesting things happen just before closing time. The details matter here: the smell of the place, the sound of footsteps on old floors, the way conversations drift and return. These are the things you can''t plan for and can''t fake.</p><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday.</p><h2>Why it matters</h2><p>It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly. It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly.</p><blockquote><p>The trick is to start before you feel ready. Nobody ever feels ready.</p></blockquote><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday.</p><img src="https://picsum.photos/seed/byb-inline-4/1200/700" alt=""><h2>How it began</h2><p>What struck me most was how ordinary it all seemed from the outside, and how extraordinary it felt once I was part of it. The people involved never described what they did as remarkable; to them it was simply Tuesday. I''ll be going back. I suspect you will too, once you''ve been once.</p>', 'https://picsum.photos/seed/byb-notes-from-a-midnight-cinema/1600/1000', (select id from public.categories where slug = 'culture'), (select id from admin_user), 'magazine', 'published', false, now() - interval '8 days 17 hours'),
  ('The Coat You Will Wear for Twenty Years', 'the-coat-you-will-wear-for-twenty-years', 'On buying less, buying once, and the tailor who talked me out of a sale.', '<p>Ask anyone who has done it, and they will tell you the hardest part was the first step. The details matter here: the smell of the place, the sound of footsteps on old floors, the way conversations drift and return. These are the things you can''t plan for and can''t fake.</p><p>The economics don''t make sense on paper. They rarely do. And yet here it is, thriving in a way that spreadsheets can''t explain.</p><h2>The people</h2><p>The economics don''t make sense on paper. They rarely do. And yet here it is, thriving in a way that spreadsheets can''t explain. The economics don''t make sense on paper. They rarely do. And yet here it is, thriving in a way that spreadsheets can''t explain.</p><blockquote><p>You don''t find the time. You take it, and then you protect it like it''s the last of something.</p></blockquote><p>It would be easy to make this a story about nostalgia, but that isn''t quite right. It is a story about attention — about choosing what to notice and then noticing it properly.</p><img src="https://picsum.photos/seed/byb-inline-5/1200/700" alt=""><h2>What it takes</h2><p>The economics don''t make sense on paper. They rarely do. And yet here it is, thriving in a way that spreadsheets can''t explain. I left later than I meant to, which is usually the sign of a good day.</p>', 'https://picsum.photos/seed/byb-the-coat-you-will-wear-for-twenty-years/1600/1000', (select id from public.categories where slug = 'style'), (select id from admin_user), 'magazine', 'published', true, now() - interval '10 days 2 hours'),
